import {s,connect,message} from '../accounts.mjs';
const $=id=>document.getElementById(id);let b,rows=[];
function note(t){$('message').textContent=t}
async function load(){const result=await s.getDocs(s.query(s.collection(b.db,'customerAccounts'),s.limit(1000)));rows=result.docs.map(x=>({id:x.id,...x.data()}));render();note('מוצגים עד 1,000 לקוחות')}
function localDate(ms){const d=new Date(ms);return new Date(ms-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function render(){$('cards').replaceChildren();const term=$('search').value.trim().toLowerCase();for(const a of rows.filter(a=>(a.businessName+' '+a.email+' '+a.number).toLowerCase().includes(term))){const card=document.createElement('section'),h=document.createElement('h2'),p=document.createElement('p'),expiry=document.createElement('input'),label=document.createElement('label');h.textContent=a.businessName;p.textContent=[a.email,a.number,a.status,a.expiresAt?'עד '+new Date(a.expiresAt).toLocaleString('he-IL'):'ללא תוקף'].join(' · ');label.textContent='תוקף לפי השעה המקומית במכשיר המנהל';expiry.type='datetime-local';expiry.value=localDate(a.expiresAt>Date.now()?a.expiresAt:Date.now()+30*86400000);label.append(expiry);card.append(h,p,label);for(const [text,status] of [['פתיחה / הארכה','active'],['חסימה','blocked']]){const button=document.createElement('button');button.textContent=text;button.onclick=async()=>{button.disabled=true;try{const end=new Date(expiry.value).getTime();if(!Number.isFinite(end)||end<=Date.now())throw Error('בחר תוקף עתידי');await s.updateDoc(s.doc(b.db,'customerAccounts',a.id),{status,expiresAt:end,updatedAt:s.serverTimestamp()});await load();note('כרטיס הלקוח עודכן')}catch(e){note(message(e))}finally{button.disabled=false}};card.append(button)}$('cards').append(card)}}
async function enter(){const owner=await s.getDocFromServer(s.doc(b.db,'settings','accountOwner'));if(owner.data()?.uid!==b.auth.currentUser?.uid)throw Error('לחשבון זה אין הרשאת מנהל');$('login').hidden=true;$('panel').hidden=false;await load()}
$('login').onsubmit=async e=>{e.preventDefault();try{b=await connect(true);await s.signInWithEmailAndPassword(b.auth,$('login').elements.email.value.trim(),$('login').elements.password.value);await enter()}catch(e){note(message(e))}};
$('logout').onclick=async()=>{await s.signOut(b.auth);location.reload()};$('refresh').onclick=()=>load().catch(e=>note(message(e)));$('search').oninput=render;
connect(true).then(async c=>{b=c;if(b.auth.currentUser)await enter()}).catch(e=>note(message(e)));
